#!/usr/bin/env python3
"""Flight Sentinel Cloud Full V2.9 para GitHub Pages.

Mantiene la experiencia rica del dashboard V2.7 sobre GitHub Actions + Pages.
GitHub Pages es estático: las acciones que requieren ejecutar Python o escribir
configuración abren un Issue de comando prellenado. El owner confirma su creación,
GitHub Actions ejecuta la operación y no se expone ningún token en el HTML.
"""
from __future__ import annotations

import argparse
import json
import os
from pathlib import Path

from src.cloud_state import load_state, sync_monitors
from src.date_utils import format_date_ui
from src.google_flights_link import build_google_flights_url_from_offer
from src.monitor_registry import load_monitors
from src.normalizer import normalize_airline


def _prepare_offer(row: dict | None) -> dict | None:
    if not isinstance(row, dict):
        return row
    out = dict(row)
    if not out.get("exact_google_url"):
        try:
            out["google_search_url"] = build_google_flights_url_from_offer(out)
        except Exception:
            out["google_search_url"] = "https://www.google.com/travel/flights"
    else:
        out["google_search_url"] = out.get("exact_google_url")
    return out


def _prepare_snapshot(snapshot: dict | None) -> dict:
    snap = dict(snapshot or {})
    snap["best"] = _prepare_offer(snap.get("best"))
    snap["offers"] = [_prepare_offer(x) for x in (snap.get("offers") or []) if isinstance(x, dict)]
    return snap


def prepare_state(state: dict, monitors_file: str) -> dict:
    profiles = load_monitors(monitors_file) if Path(monitors_file).exists() else []
    sync_monitors(state, profiles, prune=True)
    airline_codes: set[str] = set()
    for node in (state.get("monitors") or {}).values():
        for key in ("last_watch", "previous_watch", "last_audit", "previous_audit"):
            node[key] = _prepare_snapshot(node.get(key))
        verified = dict(node.get("last_verified") or {})
        verified["offers"] = [_prepare_offer(x) for x in (verified.get("offers") or []) if isinstance(x, dict)]
        node["last_verified"] = verified
        for flex_key in ("last_flex", "previous_flex"):
            flex = dict(node.get(flex_key) or {})
            rows = []
            for row in (flex.get("grid") or []):
                item = dict(row)
                if isinstance(item.get("verified_offer"), dict):
                    item["verified_offer"] = _prepare_offer(item.get("verified_offer"))
                rows.append(item)
            flex["grid"] = rows
            if isinstance(flex.get("best"), dict) and isinstance(flex["best"].get("verified_offer"), dict):
                flex["best"] = dict(flex["best"])
                flex["best"]["verified_offer"] = _prepare_offer(flex["best"].get("verified_offer"))
            node[flex_key] = flex
        for key in ("last_watch", "previous_watch", "last_audit", "previous_audit"):
            snap = node.get(key) or {}
            airline_codes.update(str(x) for x in (snap.get("airlines") or []) if x)
            for off in snap.get("offers") or []:
                airline_codes.update(str(x) for x in (off.get("airlines") or []) if x)
    state["airline_names"] = {c: normalize_airline(c) for c in sorted(airline_codes)}
    # El catálogo sale de la misma dependencia Fli usada por WATCH. No agregamos
    # un servicio externo ni una API paga para resolver destinos.
    airports = []
    try:
        from fli.models import Airport
        airports = [{"code": a.name, "name": str(a.value)} for a in Airport]
    except Exception:
        airports = [
            {"code": "MIA", "name": "Miami International Airport"},
            {"code": "AUA", "name": "Queen Beatrix International Airport"},
            {"code": "PUJ", "name": "Punta Cana International Airport"},
            {"code": "CUN", "name": "Cancún International Airport"},
            {"code": "MCO", "name": "Orlando International Airport"},
            {"code": "JFK", "name": "John F. Kennedy International Airport"},
            {"code": "MAD", "name": "Adolfo Suárez Madrid-Barajas Airport"},
        ]
    state["airports"] = airports
    state["airport_aliases"] = {
        "AUA": "Aruba · Oranjestad", "MIA": "Miami", "PUJ": "Punta Cana",
        "CUN": "Cancún", "MCO": "Orlando", "JFK": "Nueva York · JFK",
        "EWR": "Nueva York · Newark", "MAD": "Madrid", "BCN": "Barcelona",
        "FCO": "Roma", "CDG": "París", "GRU": "São Paulo", "GIG": "Río de Janeiro",
        "SCL": "Santiago de Chile", "LIM": "Lima", "BOG": "Bogotá",
    }
    return state

