JS = 'const D=window.FLIGHT_DATA, A=D.airline_names||{}, G=D.github||{};\nconst $=s=>document.querySelector(s); const app=$(\'#content\');\nconst esc=v=>String(v??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nconst money=(v,c=\'USD\')=>v==null||v===\'\'?\'—\':`${c} ${Number(v).toLocaleString(\'en-US\',{minimumFractionDigits:2,maximumFractionDigits:2})}`;\nconst isoToUI=s=>{if(!s)return\'—\';const m=String(s).slice(0,10).match(/^(\\d{4})-(\\d{2})-(\\d{2})$/);return m?`${m[3]}/${m[2]}/${m[1]}`:String(s)};\nconst dateTimeUI=s=>{if(!s)return\'—\';const d=new Date(s);if(Number.isNaN(d.getTime()))return String(s).replace(\'T\',\' \');return d.toLocaleString(\'es-AR\',{day:\'2-digit\',month:\'2-digit\',year:\'numeric\',hour:\'2-digit\',minute:\'2-digit\',hour12:false,timeZone:\'America/Argentina/Buenos_Aires\'})};\nconst airlineName=c=>A[c]||c||\'Aerolínea no informada\';\nconst pax=n=>(Number(n.adults||0)+(n.children_ages||[]).length)||1;\nconst monitorUrl=(id,tab=\'comparison\')=>`?monitor=${encodeURIComponent(id)}&tab=${encodeURIComponent(tab)}`;\nconst verifiedOffers=n=>((n.last_verified||{}).offers||[]).filter(x=>x&&String(x.booking_status||\'\').toUpperCase()===\'VERIFIED\'&&x.bookable_price!=null);\nconst bestVerified=n=>verifiedOffers(n).sort((a,b)=>Number(a.bookable_price)-Number(b.bookable_price))[0]||null;\nconst bestFull=n=>(n.last_audit||{}).best||null;\nconst bestWatch=n=>(n.last_watch||{}).best||null;\nconst statusBadge=n=>{const r=n.last_run||{};if(!r.status)return\'<span class="badge neutral">SIN CORRIDAS</span>\';let c=r.status===\'OK\'?\'ok\':r.status===\'ERROR\'?\'bad\':r.status===\'BUDGET_GUARD\'?\'warn\':\'info\';return `<span class="badge ${c}">${esc(r.mode||\'WATCH\')} ${esc(r.status)}</span>`};\nconst pipelineUrl=vars=>{if(!G.repo_url)return\'#\';const u=new URL(G.repo_url.replace(/\\/$/,\'\')+\'/issues/new\');const action=String(vars.FLIGHT_ACTION||\'command\'),monitor=String(vars.FLIGHT_MONITOR_ID||vars.MONITOR_ID||\'\');u.searchParams.set(\'title\',`[Flight Sentinel] ${action}${monitor?\' · \'+monitor:\'\'}`);const lines=[\'FLIGHT_SENTINEL_COMMAND_V1\',...Object.entries(vars).filter(([,v])=>v!==undefined&&v!==null&&String(v)!==\'\').map(([k,v])=>`${k}=${String(v).replace(/[\\r\\n]+/g,\' \')}`)];u.searchParams.set(\'body\',lines.join(\'\\n\'));return u.toString()};\nconst goPipeline=vars=>{if(!G.repo_url){toast(\'No se pudo detectar el repositorio GitHub\');return} location.href=pipelineUrl(vars)};\nconst toast=t=>{const e=$(\'#toast\');e.textContent=t;e.classList.add(\'show\');setTimeout(()=>e.classList.remove(\'show\'),2100)};\nconst nav=url=>{history.pushState({},\'\',url);render()};\nwindow.addEventListener(\'popstate\',render);\ndocument.addEventListener(\'click\',e=>{const a=e.target.closest(\'[data-nav]\');if(a){e.preventDefault();nav(a.getAttribute(\'href\'))}});\n\nfunction header(showNew=true){return `<div class="appbar"><div class="brand"><div class="brand-mark">✈</div><div><div class="brand-title">Flight Sentinel</div><div class="brand-sub">Cloud Full V2.8 · GitHub Actions + WATCH + consulta completa · $0</div></div></div><div class="nav-actions">${showNew?\'<a class="btn primary" data-nav href="?view=new">＋ <span class="label">Nuevo monitor</span></a>\':\'\'}</div></div>`}\nfunction footer(){return `<div class="footer">Los precios y el equipaje deben confirmarse antes de comprar. WATCH usa Fli como sensor gratuito; la consulta completa y VERIFY usan SerpApi detrás del guardia de cuota. Cobertura Google no equivale a mercado exhaustivo.</div>`}\nfunction page(body,showNew=true){app.innerHTML=header(showNew)+body+footer();bindCommon()}\nfunction bindCommon(){\n  document.querySelectorAll(\'[data-watch]\').forEach(b=>b.onclick=()=>goPipeline({FLIGHT_ACTION:\'watch\',FLIGHT_MONITOR_ID:b.dataset.watch}));\n  document.querySelectorAll(\'[data-full]\').forEach(b=>b.onclick=()=>goPipeline({FLIGHT_ACTION:\'audit\',FLIGHT_MONITOR_ID:b.dataset.full}));\n  document.querySelectorAll(\'[data-share]\').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast(\'Enlace copiado\')}catch{toast(\'No se pudo copiar el enlace\')}})\n}\n\nfunction primarySnapshot(n){return ((n.last_audit||{}).offers||[]).length?(n.last_audit||{}):(n.last_watch||{})}\nfunction primaryBest(n){const v=bestVerified(n);if(v)return v;return bestFull(n)||bestWatch(n)}\nfunction primaryPrice(n){const v=bestVerified(n);if(v)return v.bookable_price??v.search_price;const b=bestFull(n)||bestWatch(n);return b?.search_price??null}\nfunction primaryLink(n){const v=bestVerified(n),b=bestFull(n)||bestWatch(n);return v?.exact_google_url||b?.exact_google_url||b?.google_search_url||\'\'}\n\nfunction renderHome(){\n  const ms=Object.values(D.monitors||{}).sort((a,b)=>a.name.localeCompare(b.name));let cards=\'\';\n  for(const n of ms){\n    const best=primaryBest(n),price=primaryPrice(n),per=price!=null?`${money(Number(price)/pax(n),n.currency)} promedio por pasajero`:\'Todavía sin precio\';\n    const codes=best?.airlines||[],airline=codes.length?codes.map(airlineName).join(\' + \'):\'—\',route=best?.itinerary||\'—\',link=primaryLink(n),full=n.last_audit||{},watch=n.last_watch||{};\n    cards+=`<article class="card monitor-card"><div class="monitor-card-top"><div><h2 class="monitor-name">${esc(n.name)}</h2><div class="monitor-route">EZE/AEP → MIA · ${isoToUI(n.date_outbound)} → ${isoToUI(n.date_return)}</div></div><div class="status-stack"><span class="badge ${n.enabled?\'ok\':\'warn\'}">${n.enabled?\'ACTIVO\':\'PAUSADO\'}</span>${statusBadge(n)}</div></div><div class="monitor-main"><div><div class="home-price-label">${bestVerified(n)?\'Precio reservable verificado\':full.best?\'Mejor precio consulta completa\':\'Mejor tarifa WATCH\'}</div><div class="home-price">${money(price,n.currency)}</div><div class="home-price-sub">${esc(per)}</div></div><div class="home-summary"><div class="summary-cell"><div class="k">Aerolínea</div><div class="v">${esc(airline)}</div></div><div class="summary-cell"><div class="k">Resultados completos</div><div class="v">${full.offers_found??0} oferta(s)</div></div><div class="summary-cell"><div class="k">WATCH</div><div class="v">${watch.offers_found??0} oferta(s)</div></div></div></div><div class="updated">Última actualización: ${dateTimeUI((n.last_run||{}).at||D.updated_at)} · ${esc(route)}</div><div class="monitor-actions"><a class="btn primary" data-nav href="${monitorUrl(n.id)}">Ver monitor</a>${n.enabled?`<button class="btn buy" data-full="${esc(n.id)}">↻ Actualizar precios</button><button class="btn ghost" data-watch="${esc(n.id)}">⚡ WATCH rápido</button>`:\'\'}${link?`<a class="btn small" target="_blank" rel="noopener" href="${esc(link)}">↗ Mejor oferta</a>`:\'\'}<a class="btn ghost" data-nav href="?view=edit&monitor=${encodeURIComponent(n.id)}">✎ Editar</a></div></article>`\n  }\n  const q=D.quota||{};const quota=Object.keys(q).length?`<div class="cloud-note"><b>SerpApi:</b> ${esc(q.used??0)}/${esc(q.monthly_limit??0)} usadas · techo automático ${esc(q.auto_cap??0)} · ${esc(q.auto_left??0)} disponibles para automatización. La consulta manual también respeta este guardia.</div>`:\'\';\n  page(`<div class="page-head"><div class="breadcrumb">Flight Sentinel Cloud</div><h1 class="page-title">Tus monitores de vuelos</h1><div class="page-subtitle">Seguimiento frecuente con WATCH y resultados completos de Google Flights cuando actualizás precios.</div></div>${quota}${cards?`<div class="monitor-list">${cards}</div>`:\'<div class="card empty">No hay monitores. Creá el primero.</div>\'}`)\n}\n\nfunction historyPoints(n){const rows=[];for(const e of (n.history||[])){let src=e.audit||e.watch||{},verified=(e.verified||[]).filter(x=>x&&String(x.booking_status||\'\').toUpperCase()===\'VERIFIED\'&&x.bookable_price!=null).sort((a,b)=>Number(a.bookable_price)-Number(b.bookable_price)),best=verified[0]||src.best;if(best&&best.search_price!=null)rows.push({at:e.at||src.at,price:Number(best.bookable_price??best.search_price),search:Number(best.search_price),currency:best.currency||n.currency||\'USD\',mode:e.mode||\'\',status:e.status||\'\',offers:src.offers_found??0,changes:e.changes||[],email_error:e.email_error||\'\'})}return rows.sort((a,b)=>new Date(a.at)-new Date(b.at))}\nfunction deltaHtml(n){const rows=historyPoints(n);if(rows.length<2)return\'<span class="delta-pill flat">Primera referencia</span>\';const a=rows.at(-1).price,b=rows.at(-2).price,d=a-b,p=b?d/b*100:0;if(Math.abs(d)<.01)return\'<span class="delta-pill flat">Sin cambio vs. corrida anterior</span>\';return `<span class="delta-pill ${d<0?\'down\':\'up\'}">${d<0?\'↓\':\'↑\'} ${money(Math.abs(d),n.currency)} (${Math.abs(p).toFixed(1)}%) vs. anterior</span>`}\nfunction tabs(id,active){return `<nav class="tabs"><button class="tab ${active===\'comparison\'?\'active\':\'\'}" data-tab="comparison">Comparación</button><button class="tab ${active===\'details\'?\'active\':\'\'}" data-tab="details">Detalles y cobertura</button><button class="tab ${active===\'history\'?\'active\':\'\'}" data-tab="history">Histórico</button></nav>`}\n\nfunction renderMonitor(n,tab){\n  const v=bestVerified(n),full=n.last_audit||{},w=n.last_watch||{},price=primaryPrice(n),link=primaryLink(n),trust=!!(v&&v.booking_status===\'VERIFIED\');\n  const hasFull=(full.offers||[]).length>0,source=trust?\'Google Flights · Booking Options verificado\':hasFull?\'Google Flights · SerpApi · consulta completa\':\'Fli · WATCH gratuito\';\n  const cov=full.coverage_status||\'SIN CONSULTA COMPLETA\';\n  let body=`<div class="page-head"><div class="breadcrumb"><a data-nav href="?">← Monitores</a> / ${esc(n.name)}</div><h1 class="page-title">Buenos Aires → Miami</h1><div class="page-subtitle">${esc(n.name)} · ${isoToUI(n.date_outbound)} → ${isoToUI(n.date_return)}</div></div><section class="card hero"><div class="hero-top"><div><div class="hero-label">${trust?\'Precio reservable verificado\':hasFull?\'Mejor precio observado en consulta completa\':\'Mejor tarifa observada por WATCH\'}</div><div class="hero-price">${money(price,n.currency)}</div><div class="hero-per">${price!=null?money(Number(price)/pax(n),n.currency)+\' promedio por pasajero · \'+pax(n)+\' pasajero(s)\':\'Sin tarifa válida\'}</div>${deltaHtml(n)}<div class="chip-row"><span class="chip">📅 ${isoToUI(n.date_outbound)} → ${isoToUI(n.date_return)}</span><span class="chip">👥 ${Number(n.adults||0)} adulto(s) · ${(n.children_ages||[]).length} menor(es)</span><span class="chip">💺 ${esc((n.cabin_class||\'ECONOMY\').replaceAll(\'_\',\' \'))}</span><span class="chip">✈ Directo o 1 escala ≤ 2 h</span></div><div class="hero-actions">${link?`<a class="btn buy" target="_blank" rel="noopener" href="${esc(link)}">↗ Ver oferta en Google</a>`:\'\'}${n.enabled?`<button class="btn primary" data-full="${esc(n.id)}">↻ Actualizar precios</button><button class="btn ghost" data-watch="${esc(n.id)}">⚡ WATCH rápido</button>`:\'\'}<a class="btn ghost" data-nav href="?view=edit&monitor=${encodeURIComponent(n.id)}">✎ Editar monitor</a><button class="btn ghost" data-share>⌁ Compartir</button></div></div><aside class="hero-side"><div class="hero-side-row"><span>Estado</span><span class="badge ${n.enabled?\'ok\':\'warn\'}">${n.enabled?\'ACTIVO\':\'PAUSADO\'}</span></div><div class="hero-side-row"><span>Fuente principal</span><b>${esc(source)}</b></div><div class="hero-side-row"><span>Consulta completa</span><b>${full.offers_found??0} ofertas</b></div><div class="hero-side-row"><span>WATCH</span><b>${w.offers_found??0} ofertas</b></div><div class="hero-side-row"><span>Cobertura Google</span><b>${esc(cov)}</b></div><div class="hero-side-row"><span>Actualizado</span><b>${dateTimeUI((n.last_run||{}).at||D.updated_at)}</b></div></aside></div><div class="trust-box ${hasFull?\'good\':\'warn\'}"><div><div class="trust-title">${hasFull?\'Resultados completos disponibles\':\'Sólo hay resultados del sensor WATCH\'}</div><div class="trust-text">${hasFull?`La comparación usa la última consulta completa (${full.offers_found||0} ofertas). WATCH queda como sensor frecuente de cambios.`:\'WATCH puede devolver pocas alternativas y variar su cobertura. Usá “Actualizar precios” para reconstruir la comparación completa con Google Flights.\'}</div></div><span class="badge ${hasFull?\'ok\':\'warn\'}">${hasFull?\'COMPLETO\':\'WATCH\'}</span></div></section>${tabs(n.id,tab)}<div id="tabBody"></div>`;\n  page(body,false);document.querySelectorAll(\'[data-tab]\').forEach(b=>b.onclick=()=>nav(monitorUrl(n.id,b.dataset.tab)));if(tab===\'details\')renderDetails(n);else if(tab===\'history\')renderHistory(n);else renderComparison(n)\n}\n\nfunction offerDataset(n){const w=n.last_watch||{},a=n.last_audit||{};return {audit:{label:\'Consulta completa · Google Flights / SerpApi\',at:a.at,offers:a.offers||[],meta:a,previous:n.previous_audit||{}},watch:{label:\'WATCH rápido · Fli\',at:w.at,offers:w.offers||[],meta:w,previous:n.previous_watch||{}}}}\nfunction durationMinutes(off){if(Number.isFinite(Number(off.total_duration_minutes)))return Number(off.total_duration_minutes);let total=0;for(const leg of [\'outbound\',\'inbound\']){const seg=off[leg]||[];if(seg.length){const s=new Date(seg[0].departure_time),e=new Date(seg.at(-1).arrival_time);if(!Number.isNaN(s.getTime())&&!Number.isNaN(e.getTime()))total+=(e-s)/60000}}return total||999999}\nfunction durationText(off){if(off.total_duration)return off.total_duration;const m=durationMinutes(off);return m>=999999?\'—\':`${Math.floor(m/60)}h ${String(Math.round(m%60)).padStart(2,\'0\')}m`}\nfunction stopsText(v){return Number(v||0)===0?\'Directo\':`${v} escala${Number(v)===1?\'\':\'s\'}`}\nfunction routeKind(off){return Number(off.stops_outbound||0)===0&&Number(off.stops_inbound||0)===0?\'Directo / Directo\':`${stopsText(off.stops_outbound)} / ${stopsText(off.stops_inbound)}`}\nfunction groupKey(off){return [...(off.airlines||[])].sort().join(\'+\')||\'?\'}\nfunction variantCounts(rows){const m={};for(const o of rows)m[groupKey(o)]=(m[groupKey(o)]||0)+1;return m}\nfunction prevBestMap(prev){const m={};for(const o of (prev?.offers||[])){const k=groupKey(o),p=Number(o.search_price);if(Number.isFinite(p)&&(m[k]==null||p<m[k]))m[k]=p}return m}\nfunction segSummary(seg){return (seg||[]).map(s=>`${s.departure_iata} ${String(s.departure_time||\'\').slice(11,16)} → ${s.arrival_iata} ${String(s.arrival_time||\'\').slice(11,16)} · ${s.flight_number||s.carrier}`).join(\' · \')}\nfunction layoverMinutes(a,b){const x=new Date(a?.arrival_time),y=new Date(b?.departure_time);return Number.isNaN(x.getTime())||Number.isNaN(y.getTime())?null:Math.max(0,Math.round((y-x)/60000))}\nfunction bagState(off,key){const bag=off.baggage||{},vals=[\'outbound\',\'inbound\'].map(k=>(bag[k]||{})[key]).filter(Boolean);if(vals.includes(\'PAID\'))return\'PAID\';if(vals.length&&vals.every(v=>v===\'INCLUDED\'))return\'INCLUDED\';if(vals.includes(\'INCLUDED\')&&!vals.includes(\'PAID\'))return\'INCLUDED\';return\'UNKNOWN\'}\nfunction bagText(off,key){const state=bagState(off,key);if(state===\'INCLUDED\')return\'Incluido\';if(state===\'PAID\'){const p=((off.baggage||{}).outbound||{})[key+\'_price\']??((off.baggage||{}).inbound||{})[key+\'_price\'];return p!=null?`Con cargo · ${money(p,off.currency)}`:\'Con cargo · importe no informado\'}return\'No informado\'}\nfunction baggageStatus(off){return String((off.baggage||{}).status||\'\').toUpperCase()===\'VERIFIED\'?\'VERIFICADO\':\'NO VERIFICADO\'}\nfunction bookingInfo(off){return off.booking||{}}\nfunction displayPrice(off){const b=bookingInfo(off);return String(b.status||off.booking_status||\'\').toUpperCase()===\'VERIFIED\'&&off.bookable_price!=null?Number(off.bookable_price):Number(off.search_price||0)}\nfunction priceDeltaChip(off,prev){if(prev==null)return\'<span class="price-change flat">Nueva / sin comparación</span>\';const d=Number(off.search_price)-Number(prev);if(Math.abs(d)<.01)return\'<span class="price-change flat">Sin cambios</span>\';return `<span class="price-change ${d<0?\'down\':\'up\'}">${d<0?\'↓\':\'↑\'} ${money(Math.abs(d),off.currency)}</span>`}\nfunction highlightRows(rows,max=8){if(!rows.length)return[];const selected=[{offer:rows[0],label:\'MEJOR PRECIO\'}],covered=new Set(rows[0].airlines||[]),seen=new Set([rows[0].itinerary_hash]);for(const o of rows.slice(1)){if(selected.length>=max)break;if(seen.has(o.itinerary_hash))continue;const fresh=(o.airlines||[]).filter(c=>!covered.has(c));if(!fresh.length)continue;selected.push({offer:o,label:(o.airlines||[]).length>1?\'MEJOR OPCIÓN CON \'+fresh.map(airlineName).join(\' + \').toUpperCase():\'MEJOR ITINERARIO DE \'+fresh.map(airlineName).join(\' + \').toUpperCase()});(o.airlines||[]).forEach(c=>covered.add(c));seen.add(o.itinerary_hash)}return selected}\nfunction renderLeg(seg,title){if(!(seg||[]).length)return`<div class="leg"><div class="leg-title">${title}</div><div class="muted mini">Sin segmentos</div></div>`;let rows=\'\';seg.forEach((s,i)=>{rows+=`<div class="seg-row"><div class="seg-time">${String(s.departure_time||\'\').slice(11,16)}</div><div class="seg-main"><b>${esc(s.departure_iata)} → ${esc(s.arrival_iata)}</b><span>${esc(s.flight_number||s.carrier)} · ${esc(airlineName(s.carrier))}</span></div><div class="seg-time">${String(s.arrival_time||\'\').slice(11,16)}</div></div>`;if(i<seg.length-1){const lm=layoverMinutes(s,seg[i+1]);rows+=`<div class="layover">Conexión en ${esc(s.arrival_iata)} · ${lm==null?\'—\':`${Math.floor(lm/60)}h ${String(lm%60).padStart(2,\'0\')}m`}</div>`}});return`<div class="leg"><div class="leg-title">${title}</div>${rows}</div>`}\nfunction renderBooking(off){const b=bookingInfo(off);if(String(b.status||off.booking_status||\'\').toUpperCase()!==\'VERIFIED\')return`<div class="booking-box"><div class="booking-head"><div><b>Opciones de reserva</b><div class="mini muted">Itinerario todavía no verificado con Booking Options.</div></div><span class="badge warn">NO VERIFICADO</span></div></div>`;const low=b.lowest||{},direct=b.airline_direct||{},opts=b.options||[];return`<div class="booking-box"><div class="booking-head"><div><b>Opciones de reserva del itinerario exacto</b><div class="mini muted">Google Flights · Booking Options</div></div><span class="badge ok">VERIFICADO</span></div><div class="booking-main"><div class="booking-main-card"><div class="k">Precio reservable más bajo</div><div class="p">${money(low.price,off.currency)}</div><div class="seller">${esc(low.seller||off.seller||\'Vendedor\')}</div></div><div class="booking-main-card"><div class="k">Directo con aerolínea</div><div class="p">${direct.price!=null?money(direct.price,off.currency):\'—\'}</div><div class="seller">${esc(direct.seller||\'No informado\')}</div></div></div><div class="price-context">Precio observado originalmente en búsqueda: ${money(off.search_price,off.currency)}.</div><div class="booking-options">${opts.slice(0,8).map(o=>`<div class="booking-option"><div><div class="seller">${esc(o.seller||\'Vendedor\')}${o.is_airline?\' · aerolínea\':\'\'}</div><div class="fare">${esc(o.fare||\'\')}</div></div><div class="price">${money(o.price,off.currency)}</div></div>`).join(\'\')}</div></div>`}\nfunction renderBagLeg(info,title,currency){const one=(k,label)=>{const v=info?.[k];let t=\'No informado\',c=\'\';if(v===\'INCLUDED\'){t=\'Incluido\';c=\'coverage-complete\'}else if(v===\'PAID\'){const p=info?.[k+\'_price\'];t=p!=null?`Con cargo · ${money(p,currency)}`:\'Con cargo · importe no informado\';c=\'coverage-partial\'}return`<div class="bag-detail-row"><span>${label}</span><b class="${c}">${esc(t)}</b></div>`};return`<div class="baggage-leg"><div class="leg-title">${title}</div>${one(\'personal_item\',\'Artículo personal\')}${one(\'carry_on\',\'Carry-on / cabina\')}${one(\'checked_bag\',\'Equipaje en bodega\')}</div>`}\nfunction renderBaggage(off){const b=off.baggage||{},ok=String(b.status||\'\').toUpperCase()===\'VERIFIED\';return`<div class="baggage-box"><div class="baggage-head"><div><b>Equipaje de esta tarifa</b><div class="mini muted">${esc(b.source||\'Google Flights\')}</div></div><span class="badge ${ok?\'ok\':\'warn\'}">${ok?\'VERIFICADO\':\'NO VERIFICADO\'}</span></div><div class="baggage-grid">${renderBagLeg(b.outbound||{},\'IDA\',off.currency)}${renderBagLeg(b.inbound||{},\'VUELTA\',off.currency)}</div>${b.note?`<div class="mini muted" style="margin-top:7px">${esc(b.note)}</div>`:\'\'}</div>`}\n\nfunction renderOffer(off,n,bestObserved,variants,previous,label){\n  const codes=off.airlines||[],name=codes.map(airlineName).join(\' + \')||\'Aerolínea no informada\',observed=Number(off.search_price||0),shown=displayPrice(off),booked=String(bookingInfo(off).status||off.booking_status||\'\').toUpperCase()===\'VERIFIED\'&&off.bookable_price!=null,exact=off.exact_google_url,link=exact||off.google_search_url||\'\',best=Math.abs(observed-bestObserved)<.01,booking=bookingInfo(off),low=booking.lowest||{},direct=booking.airline_direct||{};\n  const delta=observed-bestObserved,pct=bestObserved?delta/bestObserved*100:0,diff=best?\'Mejor precio observado\':`+${money(delta,off.currency)} · +${pct.toFixed(1)}% vs. mejor observado`;\n  const compact=booked?`<div class="booking-compact"><div class="primary-line">Reservable con ${esc(low.seller||off.seller||\'vendedor\')}</div><div class="secondary-line">Precio observado en búsqueda: ${money(observed,off.currency)}${direct.price!=null?\' · Directo aerolínea: \'+money(direct.price,off.currency):\'\'}</div></div>`:`<div class="price-context">Precio reservable todavía no verificado para esta oferta.</div>`;\n  return `<article class="offer-card ${best?\'best\':\'\'}" data-airlines="${esc(codes.join(\'|\'))}" data-stops="${Number(off.stops_outbound||0)===0&&Number(off.stops_inbound||0)===0?\'direct\':\'stop\'}" data-price="${shown}" data-duration="${durationMinutes(off)}"><div class="offer-card-head"><div><div class="airline-name">${esc(name)}</div><div class="airline-code">${esc(codes.join(\' · \')||\'Código no informado\')}</div></div><span class="badge ${best?\'success\':\'info\'}">${esc(best?\'MEJOR PRECIO OBSERVADO\':label)}</span></div><div class="offer-price-row"><div><div class="mini muted price-label">${booked?\'PRECIO RESERVABLE VERIFICADO\':\'PRECIO OBSERVADO EN BÚSQUEDA\'}</div><div class="offer-price">${money(shown,off.currency||n.currency)}</div><div class="offer-per">${money(shown/pax(n),off.currency||n.currency)} promedio por pasajero · ${pax(n)} pasajero(s)</div></div>${priceDeltaChip(off,previous)}</div>${compact}<div class="offer-facts"><div class="fact"><span class="fact-icon">✈</span><span class="fact-label">Vuelo</span><span class="fact-value">${esc(routeKind(off))}</span></div><div class="fact"><span class="fact-icon">💼</span><span class="fact-label">Carry-on</span><span class="fact-value">${esc(bagText(off,\'carry_on\'))}</span></div><div class="fact"><span class="fact-icon">🧳</span><span class="fact-label">Bodega</span><span class="fact-value">${esc(bagText(off,\'checked_bag\'))}</span></div></div><div class="offer-bottom"><div><div class="variant">${variants} variante(s) · ${esc(durationText(off))}</div><div class="offer-diff ${best?\'good\':\'warn\'}">${esc(diff)}</div></div><span class="badge ${baggageStatus(off)===\'VERIFICADO\'?\'ok\':\'warn\'}">EQUIPAJE ${baggageStatus(off)}</span></div><div class="offer-buttons">${link?`<a class="btn ${exact?\'buy\':\'\'} small" target="_blank" rel="noopener" href="${esc(link)}">↗ ${exact?\'Ver oferta en Google\':\'Buscar en Google\'}</a>`:\'\'}<button type="button" class="btn small ghost secondary-detail" data-offer-details>Detalles</button>${off.airline_url?`<a class="btn small ghost" target="_blank" rel="noopener" href="${esc(off.airline_url)}">Web aerolínea</a>`:\'\'}</div><details class="offer-details ${best?\'best\':\'\'}"><summary>Ver itinerario, reserva y equipaje completo</summary><div class="offer-detail-body"><div class="legs">${renderLeg(off.outbound||[],\'IDA\')}${renderLeg(off.inbound||[],\'VUELTA\')}</div>${renderBooking(off)}${renderBaggage(off)}<div class="mini muted" style="margin-top:8px">El precio observado se usa para histórico y comparaciones. El precio reservable proviene de Booking Options del itinerario exacto y puede variar por vendedor.</div></div></details></article>`\n}\n\nfunction renderComparison(n){\n  const sets=offerDataset(n),available=Object.entries(sets).filter(([,v])=>v.offers.length);if(!available.length){$(\'#tabBody\').innerHTML=\'<div class="card empty">Todavía no hay ofertas guardadas. Ejecutá “Actualizar precios” para hacer una consulta completa.</div>\';return}\n  const defaultKey=sets.audit.offers.length?\'audit\':\'watch\';\n  $(\'#tabBody\').innerHTML=`<section class="section"><div class="section-head"><div><h2>Comparación de ofertas</h2><p>Una alternativa representativa por aerolínea. Podés abrir todas las variantes sin perder el detalle completo.</p></div><div class="section-actions"><button class="btn buy" data-full="${esc(n.id)}">↻ Actualizar precios</button></div></div><div class="source-strip"><div class="source-copy"><b>Fuente de comparación</b><div id="sourceMeta"></div><div id="sourceWarning"></div></div><select id="sourceSel" class="control">${available.map(([k,v])=>`<option value="${k}" ${k===defaultKey?\'selected\':\'\'}>${esc(v.label)} (${v.offers.length})</option>`).join(\'\')}</select></div><div class="offer-toolbar"><select id="airlineFilter" class="control"><option value="all">Todas las aerolíneas</option></select><select id="stopFilter" class="control"><option value="all">Directos y con escala</option><option value="direct">Sólo directos ida/vuelta</option><option value="stop">Con alguna escala</option></select><select id="sortFilter" class="control"><option value="price">Ordenar por precio</option><option value="duration">Ordenar por duración</option></select><button id="toggleAll" class="btn small ghost" type="button"></button><span class="filter-count" id="offerCount"></span></div><div class="offers-grid" id="offersGrid"></div></section>`;\n  let showAll=false;\n  const apply=()=>{\n    const key=$(\'#sourceSel\').value,set=sets[key],air=$(\'#airlineFilter\').value,stop=$(\'#stopFilter\').value,sort=$(\'#sortFilter\').value;\n    let rows=[...set.offers].filter(o=>(air===\'all\'||(o.airlines||[]).includes(air))&&(stop===\'all\'||(stop===\'direct\'?(Number(o.stops_outbound||0)===0&&Number(o.stops_inbound||0)===0):!(Number(o.stops_outbound||0)===0&&Number(o.stops_inbound||0)===0))));\n    rows.sort((a,b)=>sort===\'duration\'?durationMinutes(a)-durationMinutes(b):Number(a.search_price)-Number(b.search_price));\n    const counts=variantCounts(rows),prev=prevBestMap(set.previous),best=rows.length?Math.min(...rows.map(o=>Number(o.search_price)).filter(Number.isFinite)):0;\n    const selected=showAll?rows:highlightRows(rows,8).map(x=>x.offer),labels=new Map(highlightRows(rows,8).map(x=>[x.offer.itinerary_hash,x.label]));\n    $(\'#offersGrid\').innerHTML=selected.map((o,i)=>renderOffer(o,n,best,counts[groupKey(o)]||1,prev[groupKey(o)],showAll?`OPCIÓN #${i+1}`:(labels.get(o.itinerary_hash)||\'OPCIÓN\'))).join(\'\')||\'<div class="card empty">No hay ofertas con esos filtros.</div>\';\n    $(\'#offerCount\').textContent=`${selected.length} visible(s) · ${rows.length} válida(s)`;\n    $(\'#toggleAll\').textContent=showAll?\'Ver resumen\':`Ver todas las ofertas (${rows.length})`;\n    document.querySelectorAll(\'[data-offer-details]\').forEach(b=>b.onclick=()=>{const d=b.closest(\'.offer-card\').querySelector(\'details.offer-details\');d.open=!d.open;b.textContent=d.open?\'Ocultar detalles\':\'Detalles\'});\n  };\n  const renderSet=()=>{const key=$(\'#sourceSel\').value,set=sets[key],all=[...set.offers];$(\'#sourceMeta\').textContent=`Actualizado ${dateTimeUI(set.at)} · ${set.meta.offers_found||all.length} ofertas · ${(set.meta.airlines||[]).length} aerolíneas${key===\'audit\'?` · cobertura ${set.meta.coverage_status||\'UNKNOWN\'} ${set.meta.outbound_explored??0}/${set.meta.outbound_detected??0}`:\'\'}`;$(\'#sourceWarning\').innerHTML=key===\'watch\'?\'<span class="source-warning">WATCH es un sensor rápido y puede mostrar pocas alternativas. Para comparar el mercado de Google usá la consulta completa.</span>\':\'\';const af=$(\'#airlineFilter\'),old=af.value,codes=[...new Set(all.flatMap(o=>o.airlines||[]))].sort();af.innerHTML=\'<option value="all">Todas las aerolíneas</option>\'+codes.map(c=>`<option value="${esc(c)}">${esc(airlineName(c))} · ${esc(c)}</option>`).join(\'\');if(codes.includes(old))af.value=old;showAll=false;apply()};\n  $(\'#sourceSel\').onchange=renderSet;$(\'#airlineFilter\').onchange=apply;$(\'#stopFilter\').onchange=apply;$(\'#sortFilter\').onchange=apply;$(\'#toggleAll\').onclick=()=>{showAll=!showAll;apply()};bindCommon();renderSet()\n}\n\nfunction eventHtml(e){const ch=e.changes||[],txt=ch.map(x=>x.message||x.type).join(\' · \')||e.error||\'Sin cambio material\',c=e.status===\'OK\'?\'ok\':e.status===\'ERROR\'?\'bad\':e.status===\'BUDGET_GUARD\'?\'warn\':\'info\';return `<div class="event"><div class="event-time">${dateTimeUI(e.at)}</div><div><div class="event-title">${esc(e.mode||\'EVENTO\')} · ${esc(e.status||\'\')}</div><div class="event-text">${esc(txt)}</div>${e.email_error?`<div class="event-text coverage-bad">Email: ${esc(e.email_error)}</div>`:\'\'}</div><span class="badge ${c}">${esc(e.status||\'INFO\')}</span></div>`}\nfunction renderDetails(n){\n  const w=n.last_watch||{},a=n.last_audit||{},v=bestVerified(n),q=D.quota||{},events=[...(n.history||[])].reverse().slice(0,12),codes=[...new Set([...(a.airlines||[]),...(w.airlines||[])])].sort();\n  $(\'#tabBody\').innerHTML=`<section class="section"><div class="section-head"><div><h2>Estado técnico y cobertura</h2><p>La consulta completa es la fuente para comparar ofertas; WATCH queda como sensor frecuente.</p></div><div class="section-actions"><button class="btn buy" data-full="${esc(n.id)}">↻ Actualizar precios</button><button class="btn ghost" data-watch="${esc(n.id)}">⚡ WATCH rápido</button></div></div><section class="card card-pad"><div class="metrics-grid"><div class="metric"><div class="k">Cobertura Google</div><div class="v ${a.coverage_status===\'COMPLETE\'?\'coverage-complete\':\'coverage-partial\'}">${esc(a.coverage_status||\'SIN CONSULTA\')}</div><div class="hint">${a.outbound_explored??0}/${a.outbound_detected??0} salidas</div></div><div class="metric"><div class="k">Ofertas completas</div><div class="v">${a.offers_found??0}</div><div class="hint">Google Flights · SerpApi</div></div><div class="metric"><div class="k">WATCH gratuito</div><div class="v">${w.offers_found??0}</div><div class="hint">Fli · sensor</div></div><div class="metric"><div class="k">Aerolíneas</div><div class="v">${codes.length}</div><div class="hint">${esc(codes.join(\', \')||\'—\')}</div></div><div class="metric"><div class="k">Precio reservable</div><div class="v">${v?money(v.bookable_price??v.search_price,v.currency):\'—\'}</div><div class="hint">${esc(v?.seller||\'sin verificación\')}</div></div><div class="metric"><div class="k">Consultas última completa</div><div class="v">${a.queries_used??0}</div><div class="hint">incluye verificaciones</div></div><div class="metric"><div class="k">SerpApi usada</div><div class="v">${q.used??\'—\'}/${q.monthly_limit??\'—\'}</div><div class="hint">techo automático ${q.auto_cap??\'—\'}</div></div><div class="metric"><div class="k">Reserva protegida</div><div class="v">${q.reserve??30}</div><div class="hint">consultas fuera del techo</div></div></div></section><section class="section"><div class="section-head"><div><h2>Política de búsqueda</h2><p>Estas reglas son obligatorias y no se relajan.</p></div></div><section class="card card-pad"><div class="policy-card"><div class="policy-item"><div class="k">Origen</div><div class="v">EZE + AEP</div></div><div class="policy-item"><div class="k">Destino</div><div class="v">MIA</div></div><div class="policy-item"><div class="k">Escalas</div><div class="v">0 o 1 por tramo</div></div><div class="policy-item"><div class="k">Conexión máxima</div><div class="v">2 horas</div></div></div></section></section><section class="section"><div class="section-head"><div><h2>Aerolíneas encontradas</h2><p>Código IATA + descripción normalizada.</p></div></div><section class="card card-pad"><div class="airline-catalog">${codes.map(c=>`<span class="airline-chip"><b>${esc(c)}</b> · ${esc(airlineName(c))}</span>`).join(\'\')||\'<span class="muted">Sin aerolíneas registradas.</span>\'}</div></section></section><div class="cloud-note"><b>Validación independiente:</b> la auditoría automática contra Despegar no se usa en cloud porque su protección anti-bot la vuelve inestable. No se inventa cobertura de mercado a partir de un scraper bloqueado.</div><div class="section-head" style="margin-top:18px"><div><h2>Actividad reciente</h2><p>Hechos registrados por el monitor.</p></div></div><div class="event-list">${events.map(eventHtml).join(\'\')||\'<div class="empty">Sin actividad.</div>\'}</div></section>`;bindCommon()\n}\n\nlet histPeriod=\'14\';\nfunction svgChart(rows,currency){if(rows.length<2)return\'<div class="empty" style="padding:80px 10px">El gráfico aparecerá después de 2 corridas con precio.</div>\';const vals=rows.map(r=>r.price),lo=Math.min(...vals),hi=Math.max(...vals),span=(hi-lo)||1,w=760,h=260,l=58,r=20,t=22,b=34,pts=rows.map((x,i)=>({x:l+(w-l-r)*(i/(rows.length-1)),y:t+(h-t-b)*(1-(x.price-lo)/span),...x})),poly=pts.map(p=>`${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(\' \'),area=`M ${pts[0].x} ${h-b} L `+pts.map(p=>`${p.x} ${p.y}`).join(\' L \')+` L ${pts.at(-1).x} ${h-b} Z`;let grid=\'\';for(let i=0;i<5;i++){const y=t+(h-t-b)*(i/4),v=hi-span*(i/4);grid+=`<line x1="${l}" y1="${y}" x2="${w-r}" y2="${y}" stroke="#1b3550"/><text x="${l-7}" y="${y+4}" fill="#7890a7" font-size="10" text-anchor="end">${Math.round(v)}</text>`}return`<svg class="chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${grid}<path d="${area}" fill="#27B067" opacity=".08"/><polyline points="${poly}" fill="none" stroke="#27B067" stroke-width="3" vector-effect="non-scaling-stroke"/>${pts.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="#52d187"><title>${dateTimeUI(p.at)} · ${money(p.price,currency)}</title></circle>`).join(\'\')}</svg>`}\nfunction renderHistory(n){\n  const all=historyPoints(n),cut=()=>{if(histPeriod===\'all\')return all;const d=new Date();d.setDate(d.getDate()-Number(histPeriod));return all.filter(r=>new Date(r.at)>=d)};\n  const draw=()=>{const rows=cut(),vals=rows.map(r=>r.price),cur=vals.at(-1),best=vals.length?Math.min(...vals):null,worst=vals.length?Math.max(...vals):null,prev=vals.length>1?vals.at(-2):null,chg=cur!=null&&prev!=null?cur-prev:null,chron=[...rows].reverse();\n    $(\'#tabBody\').innerHTML=`<section class="section"><div class="section-head"><div><h2>Histórico de precios</h2><p>${isoToUI(n.date_outbound)} → ${isoToUI(n.date_return)} · evolución del mejor precio válido por corrida.</p></div><div class="section-actions"><button class="btn" id="csvBtn">↓ Descargar CSV</button><button class="btn ghost" data-share>⌁ Compartir</button></div></div><section class="card card-pad"><div class="stats-grid"><div class="stat-card"><div class="label">Precio actual</div><div class="value">${money(cur,n.currency)}</div><div class="sub">última corrida con precio</div></div><div class="stat-card"><div class="label">Mejor precio</div><div class="value coverage-complete">${money(best,n.currency)}</div><div class="sub">mínimo del período</div></div><div class="stat-card"><div class="label">Peor precio</div><div class="value">${money(worst,n.currency)}</div><div class="sub">máximo del período</div></div><div class="stat-card"><div class="label">Cambio vs. anterior</div><div class="value ${chg<0?\'coverage-complete\':chg>0?\'coverage-bad\':\'\'}">${chg==null?\'—\':(chg<0?\'−\':chg>0?\'+\':\'\')+money(Math.abs(chg),n.currency)}</div><div class="sub">${chg!=null&&prev?((chg/prev)*100).toFixed(1)+\'%\':\'sin comparación\'}</div></div></div><div class="periods">${[[\'7\',\'7 días\'],[\'14\',\'14 días\'],[\'30\',\'30 días\'],[\'all\',\'Todo\']].map(([p,l])=>`<button class="period ${histPeriod===p?\'active\':\'\'}" data-period="${p}">${l}</button>`).join(\'\')}</div><div class="chart-card" style="padding:0">${svgChart(rows,n.currency)}</div><div class="insight"><b>Lectura del histórico:</b> ${cur==null?\'No hay precios válidos en el período.\':Math.abs(cur-best)<.01?`El precio actual (${money(cur,n.currency)}) coincide con el mínimo registrado.`:`El precio actual está ${money(cur-best,n.currency)} por encima del mínimo (${money(best,n.currency)}).`}</div><div class="section-head" style="margin-top:20px"><div><h2>Cambios registrados</h2><p>Sólo hechos observados; no se infieren causas.</p></div></div><div class="timeline">${timelineHtml([...rows].reverse())}</div>${rawHistoryTable([...rows].reverse(),n.currency)}</section></section>`;\n    document.querySelectorAll(\'[data-period]\').forEach(b=>b.onclick=()=>{histPeriod=b.dataset.period;draw()});$(\'#csvBtn\').onclick=()=>downloadCsv(n,all);bindCommon()\n  };draw()\n}\nfunction timelineHtml(rows){if(!rows.length)return\'<div class="empty">Sin eventos en este período.</div>\';const items=rows.map((r,i)=>{const prev=rows[i+1]?.price,d=prev==null?null:r.price-prev,css=d==null||Math.abs(d)<.01?\'neutral\':d<0?\'down\':\'up\',title=d==null?\'Primera referencia del período\':Math.abs(d)<.01?\'Precio sin cambios\':d<0?\'Precio bajó\':\'Precio subió\',change=d==null?money(r.price,r.currency):Math.abs(d)<.01?\'0\':`${d<0?\'−\':\'+\'}${money(Math.abs(d),r.currency)}`;return`<div class="timeline-item ${css}"><div class="timeline-date">${dateTimeUI(r.at)}</div><div><div class="timeline-title">${title}</div><div class="timeline-desc">${money(r.price,r.currency)} · ${r.offers} oferta(s) · ${esc(r.mode)}</div></div><div class="timeline-change ${css}">${change}</div></div>`});return items.slice(0,5).join(\'\')+(items.length>5?`<details class="timeline-more"><summary>Ver ${items.length-5} cambio(s) más</summary><div class="timeline">${items.slice(5).join(\'\')}</div></details>`:\'\')}\nfunction rawHistoryTable(rows,currency){return`<details class="raw-details"><summary>Ver datos técnicos de las corridas (${rows.length})</summary><div class="table-wrap"><table class="table"><thead><tr><th>Corrida</th><th>Modo</th><th>Precio</th><th>Ofertas</th><th>Estado</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${dateTimeUI(r.at)}</td><td>${esc(r.mode)}</td><td><b>${money(r.price,r.currency||currency)}</b></td><td>${r.offers}</td><td>${esc(r.status||\'OK\')}</td></tr>`).join(\'\')||\'<tr><td colspan="5">Sin datos</td></tr>\'}</tbody></table></div></details>`}\nfunction downloadCsv(n,rows){const lines=[[\'corrida\',\'precio\',\'precio_observado\',\'moneda\',\'modo\',\'estado\',\'ofertas\'],...rows.map(r=>[r.at,r.price,r.search,r.currency,r.mode,r.status,r.offers])].map(a=>a.map(v=>`"${String(v??\'\').replaceAll(\'"\',\'""\')}"`).join(\',\')).join(\'\\n\'),blob=new Blob([lines],{type:\'text/csv;charset=utf-8\'}),a=document.createElement(\'a\');a.href=URL.createObjectURL(blob);a.download=`flight-sentinel-${n.id}-history.csv`;a.click();URL.revokeObjectURL(a.href)}\n\nfunction renderForm(n){\n  const edit=!!n,id=edit?n.id:\'\',children=edit?(n.children_ages||[]).join(\',\'):\'\';\n  page(`<div class="form-shell"><div class="page-head"><div class="breadcrumb"><a data-nav href="${edit?monitorUrl(n.id):\'?\'}">← ${edit?\'Monitor\':\'Monitores\'}</a> / ${edit?\'Editar\':\'Nuevo\'}</div><h1 class="page-title">${edit?\'Editar monitor\':\'Nuevo monitor\'}</h1><div class="page-subtitle">Configurá fechas y pasajeros. Ruta, máximo de escalas y layover permanecen protegidos.</div></div><section class="card form-card"><form id="monitorForm">${!edit?`<div class="form-group"><label class="form-label">ID corto</label><input class="input" id="fId" required pattern="[a-z0-9_-]{2,50}" placeholder="miami-diciembre"><div class="form-help">Sólo letras minúsculas, números, guion o guion bajo.</div></div>`:`<input type="hidden" id="fId" value="${esc(id)}">`}<div class="form-section"><h2>Identificación</h2><p>Un nombre claro ayuda cuando seguís varias ventanas de fechas.</p><div class="form-group"><label class="form-label">Nombre</label><input class="input" id="fName" value="${esc(n?.name||\'\')}" required placeholder="Miami · vacaciones diciembre"></div></div><div class="form-section"><h2>Ruta y fechas</h2><p>La ruta está fijada en Buenos Aires → Miami.</p><div class="route-lock"><div class="airport-box"><div class="airport-code">EZE + AEP</div><div class="airport-name">Buenos Aires · orígenes incluidos</div></div><div class="route-arrow">→</div><div class="airport-box"><div class="airport-code">MIA</div><div class="airport-name">Miami International Airport</div></div></div><div class="form-row"><div class="form-group"><label class="form-label">Fecha de ida</label><input class="input" id="fOut" value="${esc(edit?isoToUI(n.date_outbound):\'\')}" required placeholder="DD/MM/AAAA" inputmode="numeric" maxlength="10"><div class="form-help">Formato DD/MM/AAAA</div></div><div class="form-group"><label class="form-label">Fecha de vuelta</label><input class="input" id="fRet" value="${esc(edit?isoToUI(n.date_return):\'\')}" required placeholder="DD/MM/AAAA" inputmode="numeric" maxlength="10"><div class="form-help">Formato DD/MM/AAAA</div></div></div></div><div class="form-section"><h2>Pasajeros</h2><p>El precio por pasajero es promedio; el proveedor puede tarifar distinto a menores.</p><div class="form-row"><div class="form-group"><label class="form-label">Adultos</label><input class="input" id="fAdults" type="number" min="1" max="9" value="${esc(n?.adults||2)}"></div><div class="form-group"><label class="form-label">Edades de menores</label><input class="input" id="fChildren" value="${esc(children)}" placeholder="8,10"><div class="form-help">Separadas por coma. Vacío si no viajan menores.</div></div></div></div><div class="form-section"><h2>Preferencias de vuelo</h2><p>La cabina es editable. Las restricciones de escalas son la política fija.</p><input type="hidden" id="fCabin" value="${esc(n?.cabin_class||\'ECONOMY\')}"><div class="form-group"><label class="form-label">Clase de cabina</label><div class="choice-group" id="cabinChoices">${[[\'ECONOMY\',\'Economía\'],[\'PREMIUM_ECONOMY\',\'Premium Economy\'],[\'BUSINESS\',\'Business\'],[\'FIRST\',\'Primera\']].map(([v,l])=>`<button type="button" class="choice ${(n?.cabin_class||\'ECONOMY\')===v?\'active\':\'\'}" data-cabin="${v}">${l}</button>`).join(\'\')}</div></div><div class="form-group"><label class="form-label">Escalas permitidas</label><div class="choice-group readonly-choices"><span class="choice active">Directo o 1 escala</span><span class="choice active">Escala máxima 2 h</span><span class="choice">2+ escalas descartadas</span></div></div></div><div class="form-section"><h2>Estado</h2><p>Un monitor pausado conserva configuración e histórico pero no participa de los schedules.</p><div class="toggle-row"><div><b>Monitor activo</b><div class="mini muted">Disponible para nuevas consultas.</div></div><input id="fEnabled" type="checkbox" ${n?.enabled!==false?\'checked\':\'\'}></div></div><div class="form-section"><h2>Después de guardar</h2><p>La consulta completa reconstruye la lista rica de ofertas; WATCH sólo actualiza el sensor.</p><label class="toggle-row"><div><b>Actualizar precios al guardar</b><div class="mini muted">Ejecuta consulta completa Google Flights con guardia de cuota.</div></div><input id="fRun" type="checkbox"></label></div><div class="cloud-note"><b>Cómo se guarda en cloud:</b> al tocar Guardar se abre GitHub con un comando prellenado. Confirmás <b>Create issue</b>, GitHub Actions procesa el comando y actualiza <code>monitors.yaml</code> con su token efímero. El dashboard no publica credenciales.</div><div class="form-actions"><button class="btn primary" type="submit">Guardar cambios</button><a class="btn" data-nav href="${edit?monitorUrl(n.id):\'?\'}">Cancelar</a></div></form>${edit?`<div class="danger-zone"><h3>Zona de peligro</h3><p>Eliminar quita la configuración activa. El histórico cloud se archiva.</p><button class="btn danger" id="deleteBtn">🗑 Eliminar monitor</button></div>`:\'\'}</section></div>`,false);\n  document.querySelectorAll(\'[data-cabin]\').forEach(b=>b.onclick=()=>{document.querySelectorAll(\'[data-cabin]\').forEach(x=>x.classList.remove(\'active\'));b.classList.add(\'active\');$(\'#fCabin\').value=b.dataset.cabin});\n  const mask=x=>{let d=x.value.replace(/\\D/g,\'\').slice(0,8);if(d.length>4)d=d.slice(0,2)+\'/\'+d.slice(2,4)+\'/\'+d.slice(4);else if(d.length>2)d=d.slice(0,2)+\'/\'+d.slice(2);x.value=d};[\'#fOut\',\'#fRet\'].forEach(s=>$(s).addEventListener(\'input\',e=>mask(e.target)));\n  $(\'#monitorForm\').onsubmit=e=>{e.preventDefault();const id=$(\'#fId\').value.trim().toLowerCase(),name=$(\'#fName\').value.trim(),out=$(\'#fOut\').value.trim(),ret=$(\'#fRet\').value.trim(),adults=$(\'#fAdults\').value,children=$(\'#fChildren\').value.trim(),cabin=$(\'#fCabin\').value,enabled=$(\'#fEnabled\').checked;if(!/^[a-z0-9][a-z0-9_-]{1,49}$/.test(id)){toast(\'ID inválido\');return}if(!/^\\d{2}\\/\\d{2}\\/\\d{4}$/.test(out)||!/^\\d{2}\\/\\d{2}\\/\\d{4}$/.test(ret)){toast(\'Usá fechas DD/MM/AAAA\');return}const toDate=s=>{const[d,m,y]=s.split(\'/\').map(Number);return new Date(y,m-1,d)};if(toDate(ret)<=toDate(out)){toast(\'La vuelta debe ser posterior a la ida\');return}if(children&&!children.split(\',\').every(x=>/^\\d+$/.test(x.trim())&&Number(x)>=0&&Number(x)<=17)){toast(\'Edades de menores inválidas\');return}goPipeline({FLIGHT_ACTION:\'save_monitor\',MONITOR_ID:id,MONITOR_NAME:name,MONITOR_DATE_OUTBOUND:out,MONITOR_DATE_RETURN:ret,MONITOR_ADULTS:adults,MONITOR_CHILDREN_AGES:children,MONITOR_CABIN_CLASS:cabin,MONITOR_CURRENCY:\'USD\',MONITOR_ENABLED:enabled?\'true\':\'false\',FLIGHT_RUN_AFTER_SAVE:$(\'#fRun\').checked?\'audit\':\'\'})};\n  if(edit)$(\'#deleteBtn\').onclick=()=>{if(confirm(`¿Eliminar el monitor ${n.name}?`))goPipeline({FLIGHT_ACTION:\'delete_monitor\',MONITOR_ID:n.id})}\n}\n\nfunction render(){const p=new URLSearchParams(location.search),view=p.get(\'view\'),id=p.get(\'monitor\'),tab=p.get(\'tab\')||\'comparison\';if(view===\'new\')return renderForm(null);if(view===\'edit\'){const n=(D.monitors||{})[id];return n?renderForm(n):renderHome()}if(id){const n=(D.monitors||{})[id];return n?renderMonitor(n,[\'comparison\',\'details\',\'history\'].includes(tab)?tab:\'comparison\'):renderHome()}renderHome()}\nrender();\n'

CSS_V29 = '\n.flex-grid-wrap{overflow:auto;border:1px solid var(--border);border-radius:14px;background:#081624;margin-top:16px}\n.flex-grid{border-collapse:separate;border-spacing:0;min-width:720px;width:100%;font-size:12px}.flex-grid th,.flex-grid td{padding:10px;border-right:1px solid var(--border);border-bottom:1px solid var(--border);text-align:center;min-width:105px}.flex-grid th{background:#10233a;color:#cbd9e7;position:sticky;top:0;z-index:1}.flex-grid th:first-child{left:0;z-index:2}.flex-grid td:first-child{background:#0d2033;color:#cbd9e7;font-weight:700;position:sticky;left:0}.flex-cell{display:flex;flex-direction:column;gap:3px;align-items:center}.flex-cell.best{background:var(--success-bg);margin:-10px;padding:10px;min-height:54px;justify-content:center}.flex-cell.base{outline:1px solid rgba(55,138,221,.65);outline-offset:-4px}.flex-price{font-weight:800}.flex-shift{font-size:10px;color:var(--muted)}.flex-verified{font-size:9px;color:#82e8b1;font-weight:800}.flex-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:16px}.flex-summary .summary-cell{min-height:76px}.destination-search{position:relative}.destination-results{display:none;position:absolute;z-index:20;left:0;right:0;top:calc(100% + 4px);max-height:280px;overflow:auto;background:#0c1828;border:1px solid #355b7c;border-radius:12px;box-shadow:var(--shadow)}.destination-results.show{display:block}.destination-option{padding:10px 12px;cursor:pointer;border-bottom:1px solid var(--border);font-size:12px}.destination-option:hover{background:#142740}.destination-option b{display:inline-block;min-width:38px}.destination-option span{color:var(--muted)}.flex-choice-note{margin-top:8px;font-size:11px;color:var(--muted)}\n@media(max-width:760px){.flex-summary{grid-template-columns:1fr 1fr}}\n'

JS_V29 = '\nfunction header(showNew=true){return `<div class="appbar"><div class="brand"><div class="brand-mark">✈</div><div><div class="brand-title">Flight Sentinel</div><div class="brand-sub">Cloud Full V2.9 · destinos + fechas flexibles · GitHub Actions · $0</div></div></div><div class="nav-actions">${showNew?\'<a class="btn primary" data-nav href="?view=new">＋ <span class="label">Nuevo monitor</span></a>\':\'\'}</div></div>`}\nfunction bindCommon(){bindCommonV28();document.querySelectorAll(\'[data-flex]\').forEach(b=>b.onclick=()=>goPipeline({FLIGHT_ACTION:\'flex\',FLIGHT_MONITOR_ID:b.dataset.flex}))}\nfunction destinationCode(n){return String(n?.destination||\'MIA\').toUpperCase()}\nfunction airportRow(code){code=String(code||\'\').toUpperCase();return (D.airports||[]).find(x=>String(x.code).toUpperCase()===code)||null}\nfunction destinationLabel(n){const code=destinationCode(n),row=airportRow(code),alias=(D.airport_aliases||{})[code];return alias||row?.name||code}\nfunction airportSearchLabel(code){const row=airportRow(code),alias=(D.airport_aliases||{})[code];return [code,alias,row?.name].filter(Boolean).join(\' · \')}\nfunction flexLabel(n){const d=Number(n?.flex_days||0);return d>0?`±${d} día${d===1?\'\':\'s\'}`:\'Exactas\'}\nfunction renderHome(){\n  const ms=Object.values(D.monitors||{}).sort((a,b)=>a.name.localeCompare(b.name));let cards=\'\';\n  for(const n of ms){const best=primaryBest(n),price=primaryPrice(n),per=price!=null?`${money(Number(price)/pax(n),n.currency)} promedio por pasajero`:\'Todavía sin precio\';const codes=best?.airlines||[],airline=codes.length?codes.map(airlineName).join(\' + \'):\'—\',route=best?.itinerary||\'—\',link=primaryLink(n),full=n.last_audit||{},watch=n.last_watch||{},fd=Number(n.flex_days||0);cards+=`<article class="card monitor-card"><div class="monitor-card-top"><div><h2 class="monitor-name">${esc(n.name)}</h2><div class="monitor-route">EZE/AEP → ${esc(destinationCode(n))} · ${isoToUI(n.date_outbound)} → ${isoToUI(n.date_return)} · ${esc(flexLabel(n))}</div></div><div class="status-stack"><span class="badge ${n.enabled?\'ok\':\'warn\'}">${n.enabled?\'ACTIVO\':\'PAUSADO\'}</span>${statusBadge(n)}</div></div><div class="monitor-main"><div><div class="home-price-label">${bestVerified(n)?\'Precio reservable verificado\':full.best?\'Mejor precio consulta completa\':\'Mejor tarifa WATCH\'}</div><div class="home-price">${money(price,n.currency)}</div><div class="home-price-sub">${esc(per)}</div></div><div class="home-summary"><div class="summary-cell"><div class="k">Aerolínea</div><div class="v">${esc(airline)}</div></div><div class="summary-cell"><div class="k">Resultados completos</div><div class="v">${full.offers_found??0} oferta(s)</div></div><div class="summary-cell"><div class="k">Flexibilidad</div><div class="v">${esc(flexLabel(n))}</div></div></div></div><div class="updated">Última actualización: ${dateTimeUI((n.last_run||{}).at||D.updated_at)} · ${esc(route)}</div><div class="monitor-actions"><a class="btn primary" data-nav href="${monitorUrl(n.id)}">Ver monitor</a>${n.enabled?`<button class="btn buy" data-full="${esc(n.id)}">↻ Actualizar precios</button><button class="btn ghost" data-watch="${esc(n.id)}">⚡ WATCH rápido</button>${fd>0?`<button class="btn ghost" data-flex="${esc(n.id)}">⇆ Explorar ${esc(flexLabel(n))}</button>`:\'\'}`:\'\'}${link?`<a class="btn small" target="_blank" rel="noopener" href="${esc(link)}">↗ Mejor oferta</a>`:\'\'}<a class="btn ghost" data-nav href="?view=edit&monitor=${encodeURIComponent(n.id)}">✎ Editar</a></div></article>`}\n  const q=D.quota||{};const quota=Object.keys(q).length?`<div class="cloud-note"><b>SerpApi:</b> ${esc(q.used??0)}/${esc(q.monthly_limit??0)} usadas · techo automático ${esc(q.auto_cap??0)} · ${esc(q.auto_left??0)} disponibles para automatización. La exploración flexible usa primero el calendario gratuito y verifica sólo las mejores combinaciones.</div>`:\'\';page(`<div class="page-head"><div class="breadcrumb">Flight Sentinel Cloud</div><h1 class="page-title">Tus monitores de vuelos</h1><div class="page-subtitle">Elegí destino y fechas base. WATCH sigue precios exactos y Fechas flexibles busca alternativas cercanas más baratas.</div></div>${quota}${cards?`<div class="monitor-list">${cards}</div>`:\'<div class="card empty">No hay monitores. Creá el primero.</div>\'}`)\n}\nfunction tabs(id,active){return `<nav class="tabs"><button class="tab ${active===\'comparison\'?\'active\':\'\'}" data-tab="comparison">Comparación</button><button class="tab ${active===\'flex\'?\'active\':\'\'}" data-tab="flex">Fechas flexibles</button><button class="tab ${active===\'details\'?\'active\':\'\'}" data-tab="details">Detalles y cobertura</button><button class="tab ${active===\'history\'?\'active\':\'\'}" data-tab="history">Histórico</button></nav>`}\nfunction renderMonitor(n,tab){renderMonitorV28(n,tab===\'flex\'?\'comparison\':tab);const title=document.querySelector(\'.page-title\');if(title)title.textContent=`Buenos Aires → ${destinationLabel(n)} (${destinationCode(n)})`;const routeChip=document.querySelector(\'.chip-row\');if(routeChip&&!routeChip.querySelector(\'[data-v29-dest]\'))routeChip.insertAdjacentHTML(\'afterbegin\',`<span class="chip" data-v29-dest>📍 EZE/AEP → ${esc(destinationCode(n))}</span>`);const actions=document.querySelector(\'.hero-actions\');if(actions&&Number(n.flex_days||0)>0&&!actions.querySelector(\'[data-flex]\'))actions.insertAdjacentHTML(\'beforeend\',`<button class="btn ghost" data-flex="${esc(n.id)}">⇆ Explorar ${esc(flexLabel(n))}</button>`);const side=document.querySelector(\'.hero-side\');if(side&&!side.querySelector(\'[data-v29-flex]\'))side.insertAdjacentHTML(\'beforeend\',`<div class="hero-side-row" data-v29-flex><span>Fechas</span><b>${esc(flexLabel(n))}</b></div>`);document.querySelectorAll(\'.hero-side-row\').forEach(r=>{if((r.firstElementChild?.textContent||\'\').trim()===\'Cobertura Google\')r.firstElementChild.textContent=\'Cobertura consulta\'});document.querySelectorAll(\'[data-tab]\').forEach(b=>{b.onclick=()=>nav(monitorUrl(n.id,b.dataset.tab));b.classList.toggle(\'active\',b.dataset.tab===tab)});bindCommon();if(tab===\'flex\')renderFlex(n)}\nfunction flexCellPrice(row,n){return row?.verified&&row?.verified_price!=null?Number(row.verified_price):row?.price!=null?Number(row.price):null}\nfunction renderFlex(n){const host=$(\'#tabBody\'),fd=Number(n.flex_days||0),f=n.last_flex||{};if(fd<=0){host.innerHTML=`<section class="card card-pad"><h2>Fechas flexibles</h2><p class="muted">Este monitor usa fechas exactas. Editalo y elegí ±1, ±2 o ±3 días.</p><a class="btn primary" data-nav href="?view=edit&monitor=${encodeURIComponent(n.id)}">✎ Activar flexibilidad</a></section>`;return}if(!(f.grid||[]).length){host.innerHTML=`<section class="card card-pad"><h2>Fechas flexibles · ${esc(flexLabel(n))}</h2><p class="muted">Todavía no exploraste alternativas alrededor de ${isoToUI(n.date_outbound)} → ${isoToUI(n.date_return)}.</p><button class="btn primary" data-flex="${esc(n.id)}">⇆ Explorar ahora</button><div class="cloud-note" style="margin-top:14px">La grilla usa primero Fli/SearchDates como sensor gratuito. SerpApi verifica sólo las mejores combinaciones detrás del guardia mensual.</div></section>`;bindCommon();return}\n  const rows=f.grid||[],outs=[...new Set(rows.map(x=>x.date_out))].sort(),rets=[...new Set(rows.map(x=>x.date_ret))].sort(),by={};rows.forEach(x=>by[`${x.date_out}|${x.date_ret}`]=x);const best=f.best||f.sensor_best||{},bestKey=`${best.date_out||\'\'}|${best.date_ret||\'\'}`,baseKey=`${f.base_date_out||n.date_outbound}|${f.base_date_ret||n.date_return}`;let grid=`<div class="flex-grid-wrap"><table class="flex-grid"><thead><tr><th>Ida ↓ / Vuelta →</th>${rets.map(d=>`<th>${isoToUI(d)}</th>`).join(\'\')}</tr></thead><tbody>`;for(const od of outs){grid+=`<tr><td>${isoToUI(od)}</td>`;for(const rd of rets){const r=by[`${od}|${rd}`],key=`${od}|${rd}`;if(!r){grid+=\'<td>—</td>\';continue}const price=flexCellPrice(r,n),cls=`flex-cell ${key===bestKey?\'best\':\'\'} ${key===baseKey?\'base\':\'\'}`;grid+=`<td><div class="${cls}"><span class="flex-price">${money(price,r.currency||n.currency)}</span><span class="flex-shift">${Number(r.out_shift||0)>=0?\'+\':\'\'}${r.out_shift||0}d ida · ${Number(r.ret_shift||0)>=0?\'+\':\'\'}${r.ret_shift||0}d vuelta</span>${r.verified?\'<span class="flex-verified">✓ RESERVABLE</span>\':\'\'}</div></td>`}grid+=\'</tr>\'}grid+=\'</tbody></table></div>\';\n  const base=f.base_sensor?.price,cheap=f.sensor_best?.price,sav=f.sensor_savings;const bestPrice=flexCellPrice(best,n),verifiedCount=rows.filter(x=>x.verified).length;const top=[...rows].sort((a,b)=>(flexCellPrice(a,n)??1e18)-(flexCellPrice(b,n)??1e18)).slice(0,8);host.innerHTML=`<section class="card card-pad"><div class="section-head"><div><h2>Fechas flexibles · ${esc(flexLabel(n))}</h2><p>${isoToUI(f.base_date_out||n.date_outbound)} → ${isoToUI(f.base_date_ret||n.date_return)} es la referencia; la grilla no cambia el monitor automáticamente.</p></div><button class="btn primary" data-flex="${esc(n.id)}">↻ Reexplorar</button></div><div class="flex-summary"><div class="summary-cell"><div class="k">Mejor combinación</div><div class="v">${best.date_out?`${isoToUI(best.date_out)} → ${isoToUI(best.date_ret)}`:\'—\'}</div></div><div class="summary-cell"><div class="k">Mejor precio</div><div class="v">${money(bestPrice,best.currency||n.currency)}</div></div><div class="summary-cell"><div class="k">Ahorro sensor vs base</div><div class="v">${sav!=null&&Number(sav)>0?money(sav,n.currency):sav!=null?\'Sin ahorro\':\'—\'}</div></div><div class="summary-cell"><div class="k">Verificación</div><div class="v">${verifiedCount} combinación(es) reservables</div></div></div><div class="cloud-note"><b>Cómo leerla:</b> precios sin ✓ son señales del calendario de Google Flights vía Fli y pueden variar. Sólo las celdas con <b>✓ RESERVABLE</b> fueron verificadas con Booking Options. Sensor base: ${money(base,n.currency)} · mejor sensor: ${money(cheap,n.currency)} · SerpApi usado: ${esc(f.queries_used||0)} consulta(s).</div>${grid}<div class="section-head" style="margin-top:22px"><div><h2>Mejores alternativas</h2><p>Ordenadas por el mejor precio conocido para cada combinación.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Ida</th><th>Vuelta</th><th>Días</th><th>Precio</th><th>Estado</th><th></th></tr></thead><tbody>${top.map(r=>{const vo=r.verified_offer||{},url=vo.exact_google_url||vo.google_search_url||\'\';return `<tr><td>${isoToUI(r.date_out)}</td><td>${isoToUI(r.date_ret)}</td><td>${esc(r.trip_days||\'—\')}</td><td><b>${money(flexCellPrice(r,n),r.currency||n.currency)}</b></td><td>${r.verified?\'<span class="badge ok">Reservable verificado</span>\':\'<span class="badge info">Sensor flexible</span>\'}</td><td>${url?`<a class="btn small" target="_blank" rel="noopener" href="${esc(url)}">↗ Google</a>`:\'\'}</td></tr>`}).join(\'\')}</tbody></table></div></section>`;bindCommon()}\nfunction renderForm(n){\n  const edit=!!n,id=edit?n.id:\'\',children=edit?(n.children_ages||[]).join(\',\'):\'\',dest=destinationCode(n||{}),flex=Number(n?.flex_days||0);page(`<div class="form-shell"><div class="page-head"><div class="breadcrumb"><a data-nav href="${edit?monitorUrl(n.id):\'?\'}">← ${edit?\'Monitor\':\'Monitores\'}</a> / ${edit?\'Editar\':\'Nuevo\'}</div><h1 class="page-title">${edit?\'Editar monitor\':\'Nuevo monitor\'}</h1><div class="page-subtitle">Elegí destino, fechas base y cuánta flexibilidad querés explorar. EZE+AEP y la política de escalas siguen protegidos.</div></div><section class="card form-card"><form id="monitorForm">${!edit?`<div class="form-group"><label class="form-label">ID corto</label><input class="input" id="fId" required pattern="[a-z0-9_-]{2,50}" placeholder="aruba-enero"><div class="form-help">Sólo letras minúsculas, números, guion o guion bajo.</div></div>`:`<input type="hidden" id="fId" value="${esc(id)}">`}<div class="form-section"><h2>Identificación</h2><div class="form-group"><label class="form-label">Nombre</label><input class="input" id="fName" value="${esc(n?.name||\'\')}" required placeholder="Aruba · vacaciones enero"></div></div><div class="form-section"><h2>Ruta y fechas</h2><p>Los orígenes permanecen EZE + AEP; ahora podés elegir cualquier aeropuerto IATA soportado por el motor.</p><div class="route-lock"><div class="airport-box"><div class="airport-code">EZE + AEP</div><div class="airport-name">Buenos Aires · orígenes incluidos</div></div><div class="route-arrow">→</div><div class="airport-box"><div class="form-group destination-search" style="margin:0"><label class="form-label">Destino</label><input class="input" id="fDestinationSearch" autocomplete="off" value="${esc(airportSearchLabel(dest)||dest)}" placeholder="Aruba, AUA, Madrid…"><input type="hidden" id="fDestination" value="${esc(dest)}"><div class="destination-results" id="destinationResults"></div></div></div></div><div class="form-row"><div class="form-group"><label class="form-label">Fecha de ida</label><input class="input" id="fOut" value="${esc(edit?isoToUI(n.date_outbound):\'\')}" required placeholder="DD/MM/AAAA" inputmode="numeric" maxlength="10"></div><div class="form-group"><label class="form-label">Fecha de vuelta</label><input class="input" id="fRet" value="${esc(edit?isoToUI(n.date_return):\'\')}" required placeholder="DD/MM/AAAA" inputmode="numeric" maxlength="10"></div></div><input type="hidden" id="fFlex" value="${flex}"><div class="form-group"><label class="form-label">Flexibilidad de fechas</label><div class="choice-group" id="flexChoices">${[[0,\'Exactas\'],[1,\'±1 día\'],[2,\'±2 días\'],[3,\'±3 días\']].map(([v,l])=>`<button type="button" class="choice ${flex===v?\'active\':\'\'}" data-flex-choice="${v}">${l}</button>`).join(\'\')}</div><div class="flex-choice-note">Las fechas escritas arriba siguen siendo la referencia. “±3” compara cambios independientes de ida y vuelta; por ejemplo, ida +1 y vuelta +2.</div></div></div><div class="form-section"><h2>Pasajeros</h2><div class="form-row"><div class="form-group"><label class="form-label">Adultos</label><input class="input" id="fAdults" type="number" min="1" max="9" value="${esc(n?.adults||2)}"></div><div class="form-group"><label class="form-label">Edades de menores</label><input class="input" id="fChildren" value="${esc(children)}" placeholder="8,10"><div class="form-help">Separadas por coma. Vacío si no viajan menores.</div></div></div></div><div class="form-section"><h2>Preferencias de vuelo</h2><input type="hidden" id="fCabin" value="${esc(n?.cabin_class||\'ECONOMY\')}"><div class="form-group"><label class="form-label">Clase de cabina</label><div class="choice-group" id="cabinChoices">${[[\'ECONOMY\',\'Economía\'],[\'PREMIUM_ECONOMY\',\'Premium Economy\'],[\'BUSINESS\',\'Business\'],[\'FIRST\',\'Primera\']].map(([v,l])=>`<button type="button" class="choice ${(n?.cabin_class||\'ECONOMY\')===v?\'active\':\'\'}" data-cabin="${v}">${l}</button>`).join(\'\')}</div></div><div class="form-group"><label class="form-label">Escalas permitidas</label><div class="choice-group readonly-choices"><span class="choice active">Directo o 1 escala</span><span class="choice active">Escala máxima 2 h</span><span class="choice">2+ escalas descartadas</span></div></div></div><div class="form-section"><h2>Estado</h2><div class="toggle-row"><div><b>Monitor activo</b><div class="mini muted">Disponible para nuevas consultas.</div></div><input id="fEnabled" type="checkbox" ${n?.enabled!==false?\'checked\':\'\'}></div></div><div class="form-section"><h2>Después de guardar</h2><label class="toggle-row"><div><b>Actualizar precios exactos al guardar</b><div class="mini muted">Ejecuta AUDIT para las fechas base. La exploración flexible se ejecuta aparte.</div></div><input id="fRun" type="checkbox"></label></div><div class="cloud-note"><b>Cloud:</b> Guardar abre un GitHub Issue de comando prellenado; Actions actualiza <code>monitors.yaml</code>. No se publica ningún token en Pages.</div><div class="form-actions"><button class="btn primary" type="submit">Guardar cambios</button><a class="btn" data-nav href="${edit?monitorUrl(n.id):\'?\'}">Cancelar</a></div></form>${edit?`<div class="danger-zone"><h3>Zona de peligro</h3><p>Eliminar quita la configuración activa. El histórico cloud se archiva.</p><button class="btn danger" id="deleteBtn">🗑 Eliminar monitor</button></div>`:\'\'}</section></div>`,false);\n  document.querySelectorAll(\'[data-cabin]\').forEach(b=>b.onclick=()=>{document.querySelectorAll(\'[data-cabin]\').forEach(x=>x.classList.remove(\'active\'));b.classList.add(\'active\');$(\'#fCabin\').value=b.dataset.cabin});document.querySelectorAll(\'[data-flex-choice]\').forEach(b=>b.onclick=()=>{document.querySelectorAll(\'[data-flex-choice]\').forEach(x=>x.classList.remove(\'active\'));b.classList.add(\'active\');$(\'#fFlex\').value=b.dataset.flexChoice});const mask=x=>{let d=x.value.replace(/\\D/g,\'\').slice(0,8);if(d.length>4)d=d.slice(0,2)+\'/\'+d.slice(2,4)+\'/\'+d.slice(4);else if(d.length>2)d=d.slice(0,2)+\'/\'+d.slice(2);x.value=d};[\'#fOut\',\'#fRet\'].forEach(q=>$(q).addEventListener(\'input\',e=>mask(e.target)));\n  const search=$(\'#fDestinationSearch\'),results=$(\'#destinationResults\');const showDest=()=>{const q=search.value.trim().toLowerCase(),list=(D.airports||[]).filter(a=>{const code=String(a.code||\'\').toLowerCase(),name=String(a.name||\'\').toLowerCase(),alias=String((D.airport_aliases||{})[a.code]||\'\').toLowerCase();return !q||code.includes(q)||name.includes(q)||alias.includes(q)}).slice(0,12);results.innerHTML=list.map(a=>`<div class="destination-option" data-dest="${esc(a.code)}"><b>${esc(a.code)}</b> <span>${esc((D.airport_aliases||{})[a.code]||a.name)}</span></div>`).join(\'\')||\'<div class="destination-option"><span>Sin coincidencias. Probá con el código IATA.</span></div>\';results.classList.add(\'show\');document.querySelectorAll(\'[data-dest]\').forEach(o=>o.onclick=()=>{const c=o.dataset.dest;$(\'#fDestination\').value=c;search.value=airportSearchLabel(c);results.classList.remove(\'show\')})};search.addEventListener(\'focus\',showDest);search.addEventListener(\'input\',()=>{$(\'#fDestination\').value=\'\';showDest()});document.addEventListener(\'click\',e=>{if(!e.target.closest(\'.destination-search\'))results.classList.remove(\'show\')},{once:true});\n  $(\'#monitorForm\').onsubmit=e=>{e.preventDefault();const mid=$(\'#fId\').value.trim().toLowerCase(),name=$(\'#fName\').value.trim(),out=$(\'#fOut\').value.trim(),ret=$(\'#fRet\').value.trim(),adults=$(\'#fAdults\').value,children=$(\'#fChildren\').value.trim(),cabin=$(\'#fCabin\').value,enabled=$(\'#fEnabled\').checked,flex=$(\'#fFlex\').value;let destination=$(\'#fDestination\').value.trim().toUpperCase();if(!destination){const raw=search.value.trim().toUpperCase();const m=raw.match(/\\b[A-Z]{3}\\b/);destination=m?m[0]:\'\'}if(!/^[a-z0-9][a-z0-9_-]{1,49}$/.test(mid)){toast(\'ID inválido\');return}if(!/^[A-Z]{3}$/.test(destination)||[\'EZE\',\'AEP\'].includes(destination)){toast(\'Elegí un destino válido\');return}if(!/^\\d{2}\\/\\d{2}\\/\\d{4}$/.test(out)||!/^\\d{2}\\/\\d{2}\\/\\d{4}$/.test(ret)){toast(\'Usá fechas DD/MM/AAAA\');return}const toDate=s=>{const[d,m,y]=s.split(\'/\').map(Number);return new Date(y,m-1,d)};if(toDate(ret)<=toDate(out)){toast(\'La vuelta debe ser posterior a la ida\');return}if(children&&!children.split(\',\').every(x=>/^\\d+$/.test(x.trim())&&Number(x)>=0&&Number(x)<=17)){toast(\'Edades de menores inválidas\');return}goPipeline({FLIGHT_ACTION:\'save_monitor\',MONITOR_ID:mid,MONITOR_NAME:name,MONITOR_DESTINATION:destination,MONITOR_DATE_OUTBOUND:out,MONITOR_DATE_RETURN:ret,MONITOR_FLEX_DAYS:flex,MONITOR_ADULTS:adults,MONITOR_CHILDREN_AGES:children,MONITOR_CABIN_CLASS:cabin,MONITOR_CURRENCY:\'USD\',MONITOR_ENABLED:enabled?\'true\':\'false\',FLIGHT_RUN_AFTER_SAVE:$(\'#fRun\').checked?\'audit\':\'\'})};if(edit)$(\'#deleteBtn\').onclick=()=>{if(confirm(`¿Eliminar el monitor ${n.name}?`))goPipeline({FLIGHT_ACTION:\'delete_monitor\',MONITOR_ID:n.id})}\n}\nfunction render(){const p=new URLSearchParams(location.search),view=p.get(\'view\'),id=p.get(\'monitor\'),tab=p.get(\'tab\')||\'comparison\';if(view===\'new\')return renderForm(null);if(view===\'edit\'){const n=(D.monitors||{})[id];return n?renderForm(n):renderHome()}if(id){const n=(D.monitors||{})[id];return n?renderMonitor(n,[\'comparison\',\'flex\',\'details\',\'history\'].includes(tab)?tab:\'comparison\'):renderHome()}renderHome()}'

def _runtime_js() -> str:
    base = JS.rsplit("render();", 1)[0]
    base = base.replace("function bindCommon(){", "function bindCommonV28(){", 1)
    base = base.replace("function renderMonitor(n,tab){", "function renderMonitorV28(n,tab){", 1)
    return base + JS_V29 + "\nrender();\n"


def render_html(state: dict, *, repository_url: str, branch: str) -> str:
    payload = dict(state)
    payload["github"] = {"repo_url": repository_url, "branch": branch}
    data_json = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    visible_dates = " · ".join(
        f"{format_date_ui(node.get('date_outbound'))} → {format_date_ui(node.get('date_return'))}"
        for node in (state.get("monitors") or {}).values()
        if node.get("date_outbound") and node.get("date_return")
    )
    return (
        '<!doctype html><html lang="es"><head><meta charset="utf-8">'
        '<meta name="viewport" content="width=device-width,initial-scale=1">'
        '<meta name="color-scheme" content="dark">'
        f'<meta name="flight-monitor-dates" content="{visible_dates}">'
        '<title>Flight Sentinel Cloud</title>'
        f'<style>{CSS}{CSS_V29}</style></head><body><main class="app"><div id="content"></div></main>'
        '<div id="toast" class="toast"></div>'
        f'<script>window.FLIGHT_DATA={data_json};</script><script>{_runtime_js()}</script></body></html>'
    )


def render(state: dict) -> str:
    state = json.loads(json.dumps(state, ensure_ascii=False))
    airline_codes: set[str] = set()
    for node in (state.get("monitors") or {}).values():
        for key in ("last_watch", "previous_watch", "last_audit", "previous_audit"):
            snapshot = node.get(key) or {}
            airline_codes.update(str(x) for x in (snapshot.get("airlines") or []) if x)
    state.setdefault("airline_names", {c: normalize_airline(c) for c in sorted(airline_codes)})
    return render_html(
        state,
        repository_url="https://github.com/cjacobs32/flight-sentinel-miami",
        branch="main",
    )


def main() -> int:
    p = argparse.ArgumentParser()
    p.add_argument("--state", default="cloud_state/state.json")
    p.add_argument("--monitors-file", default="monitors.yaml")
    p.add_argument("--output", default="public/index.html")
    p.add_argument("--repository-url", default="")
    p.add_argument("--branch", default=os.getenv("GITHUB_DEFAULT_BRANCH", "main"))
    args = p.parse_args()

    state = prepare_state(load_state(args.state), args.monitors_file)
    repository_url = args.repository_url or (f"{os.getenv('GITHUB_SERVER_URL', 'https://github.com').rstrip('/')}/{os.getenv('GITHUB_REPOSITORY', 'cjacobs32/flight-sentinel-miami')}")
    out = Path(args.output)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(render_html(state, repository_url=repository_url, branch=args.branch), encoding="utf-8")
    (out.parent / "state.json").write_text(json.dumps(state, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"Dashboard cloud V2.9 generado: {out}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
